// Obtiene el string JSON de la salida del nodo anterior
const jsonString = $input.first().json.output;

// Convierte (parsea) el string en un objeto JSON real
const parsedJson = JSON.parse(jsonString);

// Devuelve el nuevo objeto JSON para que los siguientes nodos puedan usarlo
return [{ json: parsedJson }];

// Paso 1: Leer y parsear el input.
const inputItem = $input.first().json;
const cachedData = JSON.parse(inputItem.value);
const messages = cachedData.messages;

const finalOutput = [];
let i = 0;

while (i < messages.length) {
  const currentMessage = messages[i];

  if (currentMessage.type === 'text') {
    // Manejo de bloques de texto
    let textBuffer = [currentMessage.content];
    let nextIndex = i + 1;
    while (nextIndex < messages.length && messages[nextIndex].type === 'text') {
      textBuffer.push(messages[nextIndex].content);
      nextIndex++;
    }
    finalOutput.push({
      attachmentUrl: null,
      associatedText: textBuffer.join(' ')
    });
    i = nextIndex;

  } else if (currentMessage.type === 'attachment') { // <-- CAMBIO AQUÍ
    // Manejo de pares Adjunto -> Texto
    let associatedText = "";

    if ((i + 1) < messages.length && messages[i + 1].type === 'text') {
      associatedText = messages[i + 1].content;
      i++;
    }

    finalOutput.push({
      attachmentUrl: currentMessage.content, // <-- CAMBIO AQUÍ
      associatedText: associatedText
    });

    i++;
  } else {
    i++;
  }
}

return finalOutput.map(item => ({ json: item }));

let requests = $("Download Document1").all()

requests.forEach((request) => {
  let mime_type = request.json.mime_type

  if (
    mime_type === "text/calendar" || 
    mime_type === "application/ics" || 
    mime_type === "text/x-calendar"
  ) {
    request.json.mime_type = "mapped/calendar"
  }

  if (
    mime_type === "application/xml" || 
    mime_type === "text/xml") {
    request.json.mime_type = "mapped/xml"
  }

  if (!mime_type) {
    request.json.mime_type = $('Gets Document Source URL').first().json.mime_type
  }
})

return requests;

