// Obtenemos los datos cacheados de Redis, si existen
const redisOutput = $('Get Key Redis1').first().json.value;
let contactData;

if (!redisOutput) {
  contactData = { messages: [], lastMessageTimestamp: 0 };
} else {
  contactData = JSON.parse(redisOutput);
}

// Accedemos al cuerpo del webhook
const webhookBody = $('Webhook').first().json.body;
const customData = webhookBody.customData;

// Verificamos si hay una URL en 'message_attachment' (genérico para cualquier archivo)
if (customData.message_attachment && customData.message_attachment !== "") {
  // Si hay adjunto, lo guardamos como un objeto de tipo 'attachment'
  const attachmentObject = {
    type: 'attachment',
    content: customData.message_attachment
  };
  contactData.messages.push(attachmentObject);

  // Verificamos si también hay un texto asociado en 'message_body'
  if (customData.message_body && customData.message_body !== "") {
    // Usamos una expresión regular para limpiar CUALQUIER prefijo "type message: ..."
    const cleanedText = customData.message_body.replace(/^type message: \w+\n\n/, '');

    // Solo guardamos el texto si queda algo después de limpiar
    if (cleanedText.trim()) {
      const textObject = {
        type: 'text',
        content: cleanedText
      };
      contactData.messages.push(textObject);
    }
  }
} else {
  // Si no hay adjunto, es un mensaje de solo texto
  const textObject = {
    type: 'text',
    content: customData.message_body
  };
  contactData.messages.push(textObject);
}

// Actualizamos el timestamp como antes
contactData.lastMessageTimestamp = Date.now();

// Preparamos la salida para guardar en Redis
return {
  contactId: webhookBody.contact_id,
  updatedDataString: JSON.stringify(contactData),
  executionTimestamp: contactData.lastMessageTimestamp
};
